import { renderHook, act } from '@testing-library/react';
import { useCounter } from './useCounter';

function useCounter(initial = 0) {
  const [count, setCount] = useState(initial);
  const increment = () => setCount((c) => c + 1);
  const decrement = () => setCount((c) => c - 1);
  return { count, increment, decrement };
}

describe('useCounter', () => {
  it('starts at the initial value', () => {
    const { result } = renderHook(() => useCounter(10));
    expect(result.current.count).toBe(10);
  });

  it('increments the count', () => {
    const { result } = renderHook(() => useCounter());

    act(() => {
      result.current.increment();
    });

    expect(result.current.count).toBe(1);
  });
});

function useAsync<T>(asyncFn: () => Promise<T>) {
  const [state, setState] = useState<{
    data: T | null;
    loading: boolean;
    error: Error | null;
  }>({ data: null, loading: true, error: null });

  useEffect(() => {
    asyncFn()
      .then((data) => setState({ data, loading: false, error: null }))
      .catch((error) => setState({ data: null, loading: false, error }));
  }, [asyncFn]);

  return state;
}

test('useAsync resolves data', async () => {
  const fetchData = () => Promise.resolve({ id: 1 });
  const { result } = renderHook(() => useAsync(fetchData));

  expect(result.current.loading).toBe(true);

  await waitFor(() => expect(result.current.loading).toBe(false));
  expect(result.current.data).toEqual({ id: 1 });
  expect(result.current.error).toBeNull();
});

const ThemeContext = createContext<'light' | 'dark'>('light');

function useThemeClass() {
  const theme = useContext(ThemeContext);
  return theme === 'dark' ? 'bg-gray-900' : 'bg-white';
}

test('useThemeClass returns dark class', () => {
  const wrapper = ({ children }: { children: React.ReactNode }) => (
    <ThemeContext.Provider value="dark">{children}</ThemeContext.Provider>
  );

  const { result } = renderHook(() => useThemeClass(), { wrapper });
  expect(result.current).toBe('bg-gray-900');
});
